('Основы психологии с ИИ', 'Личность и отношения', 'ИИ-практика: Личность и отношения', 'ai_test', NULL, 3, TRUE),
('Основы психологии с ИИ', 'Личность и отношения', 'Итоговый тест: основы психологии', 'test', NULL, 4, FALSE)
) AS p(course_title, section_title, title, page_type, content, position, ai_only)
 ON p.course_title = c.title AND p.section_title = s.title
WHERE NOT p.ai_only OR c.title IN ('Основы психологии с ИИ');

INSERT INTO tests (page_id, passing_score)
SELECT p.id, CASE WHEN p.title ILIKE 'Входной тест:%' OR p.title ILIKE 'Итоговый тест:%' THEN 0 ELSE 50 END
FROM course_pages p
JOIN course_sections s ON s.id = p.section_id
JOIN courses c ON c.id = s.course_id
WHERE p.type = 'test'
 AND c.title IN ('Основы психологии', 'Основы психологии с ИИ');

